<?php
declare(strict_types=1);require __DIR__.'/verein-core.php';require __DIR__.'/thv-community-lib.php';thv_headers();thv_session();
$error='';$ready=false;$state=[];$tab=($_GET['tab']??'')==='training'?'training':'anfragen';
try{
 $state=thv_state(fn($s)=>$s);thv_need(thv_user($state),'editor','admin');if(!thv_secure())throw new DomainException('HTTPS erforderlich.');$ready=true;
 if($_SERVER['REQUEST_METHOD']==='POST'){thv_check();$action=thv_text('action',24);$id=thv_text('id',24,false);
 if(in_array($action,['inquiry-status','inquiry-delete'],true)){$tab='anfragen';$status=thv_text('status',20,false);thv_state(function(&$s)use($action,$id,$status){thv_need(thv_user($s),'editor','admin');if(!isset($s['public_inquiries'][$id]))throw new DomainException('Anfrage nicht gefunden.');if($action==='inquiry-delete'){unset($s['public_inquiries'][$id]);return;}if(!in_array($status,['pending','contacted','confirmed','waitlist','cancelled'],true))throw new DomainException('Ungültiger Status.');$s['public_inquiries'][$id]['status']=$status;},true);}
 elseif(in_array($action,['save-training','delete-training'],true)){$tab='training';$course=thv_text('course',24,false);$date=thv_text('date',10,false);$time=thv_text('time',5,false);$end=thv_text('end',5,false);$status=thv_text('status',20,false);$note=thv_text('note',400,false);
 thv_state(function(&$s)use($action,$id,$course,$date,$time,$end,$status,$note){thv_need(thv_user($s),'editor','admin');$s['training_dates']??=[];if($id&&!isset($s['training_dates'][$id]))throw new DomainException('Termin nicht gefunden.');if($action==='delete-training'){unset($s['training_dates'][$id]);return;}$courses=thv_courses($s);if(!isset($courses[$course])||in_array($course,['beratung','kontakt'],true)||!thv_day($date)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$time)||($end!==''&&(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$end)||$end<=$time))||!isset(thv_training_status()[$status]))throw new DomainException('Bitte Kurs, Datum und Uhrzeit prüfen.');if(!$id&&count($s['training_dates'])>=2000)throw new DomainException('Bitte alte Termine entfernen.');$id=$id?:thv_id();$s['training_dates'][$id]=['id'=>$id,'course'=>$course,'title'=>$courses[$course],'date'=>$date,'time'=>$time,'end'=>$end,'status'=>$status,'note'=>$note];},true);}
 else throw new DomainException('Unbekannte Aktion.');
 header('Location: vereins-tools.php?tab='.$tab.'&ok=1',true,303);exit;}
}catch(DomainException $e){$error=$e->getMessage();}catch(Throwable $e){$error='Momentan nicht verfügbar.';}
if(!$ready)http_response_code(403);thv_layout_start('Vereinszentrale');
?><div class="club-heading"><div><h1>Vereinszentrale</h1><p>Interessenten und Termine zentral betreuen.</p></div><a class="secondary" href="vereinsbereich.php">Zur Übersicht</a></div><?php if($error):?><p class="club-message error" role="alert"><?=h($error)?></p><?php endif;if($ready):?><nav class="club-tabs"><a href="?tab=anfragen" <?=$tab==='anfragen'?'aria-current="page"':''?>>Kursanfragen</a><a href="?tab=training" <?=$tab==='training'?'aria-current="page"':''?>>Trainingsplan</a><a href="vereinsbereich.php?tab=redaktion">Redaktion</a><a href="website-studio.php">Website Studio</a></nav><?php if(isset($_GET['ok'])):?><p class="club-message" role="status">Gespeichert.</p><?php endif;if($tab==='anfragen'):$labels=['pending'=>'Offen','contacted'=>'Kontaktiert','confirmed'=>'Bestätigt','waitlist'=>'Warteliste','cancelled'=>'Erledigt / abgesagt'];$filter=is_string($_GET['status']??null)?$_GET['status']:'';?><section class="club-card"><h2>Öffentliche Kursanfragen</h2><p>Interessenten benötigen kein Mitgliedskonto. Bitte kontaktiere sie und aktualisiere den Status.</p><div class="club-actions"><a class="secondary" href="?tab=anfragen">Alle</a><?php foreach($labels as $k=>$label):?><a class="secondary" href="?tab=anfragen&amp;status=<?=h($k)?>"><?=h($label)?></a><?php endforeach;?></div><?php $shown=0;foreach(array_reverse($state['public_inquiries']??[]) as $q):if($filter&&$q['status']!==$filter)continue;$shown++;?><article class="club-entry"><span class="tag"><?=h($labels[$q['status']]??'Offen')?> · <?=h(substr($q['created'],0,10))?></span><h3><?=h($q['title'])?> · <?=h($q['name'])?></h3><p><?=h($q['kind']==='trial'?'Schnupperanfrage':($q['kind']==='contact'?'Allgemeine Frage':'Kursanfrage'))?><?php if($q['dog']):?> · <?=h($q['dog'])?> (<?=h($q['age'])?>) <?=h($q['breed'])?><?php endif;?></p><p><a href="mailto:<?=h($q['email'])?>"><?=h($q['email'])?></a> <?=h($q['phone'])?></p><p class="long-text"><?=h($q['note'])?></p><p class="small">E-Mail: <?=!empty($q['mail']['office'])?'An Mailserver übergeben':'Nicht bestätigt, bitte hier bearbeiten'?></p><form method="post" class="club-form inline"><?php thv_action('inquiry-status');?><input type="hidden" name="id" value="<?=h($q['id'])?>"><?php thv_select('Status','status',$labels,$q['status']);?><button>Speichern</button></form><details><summary>Anfrage dauerhaft löschen</summary><form method="post"><?php thv_action('inquiry-delete');?><input type="hidden" name="id" value="<?=h($q['id'])?>"><button class="secondary">Endgültig löschen</button></form></details></article><?php endforeach;if(!$shown):?><p>Keine passenden Anfragen vorhanden.</p><?php endif;?></section><?php else:$edit=$state['training_dates'][is_string($_GET['edit']??null)?$_GET['edit']:'']??[];$courses=array_diff_key(thv_courses($state),array_flip(['beratung','kontakt']));?><section class="club-card"><h2>Trainingsplan</h2><p>Nur bestätigte Termine eintragen. Änderungen erscheinen öffentlich. Vergangene Termine werden ausgeblendet.</p><form method="post" class="club-form"><?php thv_action('save-training');?><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><?php thv_select('Kurs','course',$courses,$edit['course']??'welpen');thv_field('Datum','date','date',$edit['date']??date('Y-m-d'));thv_field('Beginn','time','time',$edit['time']??'');thv_field('Ende (optional)','end','time',$edit['end']??'',false);thv_select('Status','status',thv_training_status(),$edit['status']??'scheduled');thv_area('Öffentlicher Hinweis (optional)','note',$edit['note']??'',false,2);?><button>Termin speichern</button></form><div class="club-list"><?php $dates=array_values($state['training_dates']??[]);usort($dates,fn($a,$b)=>strcmp($b['date'].$b['time'],$a['date'].$a['time']));foreach($dates as $e):?><article class="club-entry"><span class="tag"><?=h(thv_training_status()[$e['status']])?></span><h3><?=h($e['title'])?></h3><p><?=h($e['date'])?> · <?=h($e['time'])?> Uhr · <?=h($e['note'])?></p><a class="secondary" href="?tab=training&amp;edit=<?=h($e['id'])?>">Bearbeiten</a><details><summary>Termin entfernen</summary><form method="post"><?php thv_action('delete-training');?><input type="hidden" name="id" value="<?=h($e['id'])?>"><button class="secondary">Entfernen</button></form></details></article><?php endforeach;?></div></section><?php endif;else:?><a class="secondary" href="vereinsbereich.php">Zum Vereinslogin</a><?php endif;thv_layout_end();?>
